    p_free_t: 'Gratis', p_free_amt: 'NT$0',
    p_free_d: '<li>Hingga 20 orang (termasuk pemimpin)</li><li>Perjalanan hingga 3 hari</li><li>Semua fitur tersedia</li><li>Anggota selalu gratis</li>',
